/**
 * The gallery hero (model gallery@1): the heading, a description, up to two links as the actions and three or
 * four photos as a list. Axes: media (end: the photos after the copy, start: before it from md up, bottom: in a
 * row under it), count (3: three square photos in a row, 4: a 2 x 2 grid, a row of four under the copy).
 */
import { type ReactNode } from "react";
import { Block, Box, Container, Group, LinkButton, List, ListItem, Stack, Text, Title } from "../compose";
import { MediaFrame } from "../components/media-frame";
import { cn, urlOf } from "../utils";
import type { GalleryPhoto } from "./gallery-hero.types";

export type GalleryHeroProps = {
  id: string;
  title: string;
  description?: string;
  actionLabel?: string;
  actionHref?: string;
  secondaryActionLabel?: string;
  secondaryActionHref?: string;
  photos: GalleryPhoto[];
  level?: 1 | 2 | 3;
  padding?: "compact" | "standard" | "spacious";
  align?: "start" | "center" | "end";
  media?: "end" | "start" | "bottom";
  count?: "3" | "4";
  landmarkLabel?: string;
};

export function GalleryHero({
  id,
  title,
  description = "",
  actionLabel = "",
  actionHref = "",
  secondaryActionLabel = "",
  secondaryActionHref = "",
  photos,
  level = 2,
  padding = "standard",
  align = "start",
  media = "end",
  count = "3",
  landmarkLabel,
}: GalleryHeroProps) {
  const titleId = id + "-title";
  const column =
    (align as string) === "center" ? "center"
    : (align as string) === "end" ? "end"
    : "start";
  const textAlign =
    (align as string) === "center" ? "text-center"
    : (align as string) === "end" ? "text-end"
    : "text-start";
  const frame =
    (media as string) === "bottom" ? "grid grid-cols-1 gap-12"
    : "grid grid-cols-1 items-center gap-12 md:grid-cols-2";
  const photoCols =
    ((media as string) === "bottom") && ((count as string) === "4") ? "grid-cols-2 md:grid-cols-4"
    : (count as string) === "4" ? "grid-cols-2"
    : "grid-cols-3";
  const photoOrder = ((media as string) === "start") ? "md:order-first" : "";
  const photoRatio =
    (media as string) === "bottom" ? "4/3"
    : (count as string) === "4" ? "4/3"
    : "1/1";
  return (
    <Block
      tag="section"
      className={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="gallery-hero"
    >
      <Container className="mx-auto w-full max-w-6xl px-4">
        <Box className={frame}>
          <Stack gap="6" align={column}>
            <Title as={level} size="4xl" weight="bold" className={cn("tracking-tight", textAlign)} id={titleId}>
              {title}
            </Title>
            {description ? (
              <Text size="lg" className={cn("text-muted-foreground", textAlign)}>
                {description}
              </Text>
            ) : null}
            {((actionLabel && actionHref) || (secondaryActionLabel && secondaryActionHref)) ? (
              <Group gap="4" align="center" justify={column} className="flex-wrap">
                {(actionLabel && actionHref) ? (
                  <LinkButton variant="default" size="lg" href={urlOf(actionHref)}>
                    {actionLabel}
                  </LinkButton>
                ) : null}
                {(secondaryActionLabel && secondaryActionHref) ? (
                  <LinkButton variant="secondary" size="lg" href={urlOf(secondaryActionHref)}>
                    {secondaryActionLabel}
                  </LinkButton>
                ) : null}
              </Group>
            ) : null}
          </Stack>
          <List tag="ul" className={cn("m-0 w-full list-none p-0", cn("grid items-start gap-4", photoCols, photoOrder))}>
            {(photos ?? []).map((p) => (
              <ListItem key={p.id} data-slot="photo">
                <MediaFrame alt={p.imageAlt} src={p.image} ratio={photoRatio} />
              </ListItem>
            ))}
          </List>
        </Box>
      </Container>
    </Block>
  );
}

